steps:
1. CREATE c:\Users\KING\number-academy\src\pages\AIAssistant.jsx:

   Structure:
   - imports: useState, useRef, useEffect from react; Send, Bot, User, Loader2 from lucide-react.
   - const SYSTEM_PROMPT: 'You are a Ghanaian Junior High School curriculum assistant trained on the NaCCA Common Core Programme. You help teachers understand curriculum standards, plan lessons, design activities, and create assessments. You are knowledgeable about Ghanaian education context, local examples, and the specific expectations of each subject strand. When asked about a topic, relate it to the appropriate NaCCA strand, sub-strand, and content standard where relevant. Be concise, practical, and encouraging.'
   - Message shape: { id: number, role: 'user'|'assistant', content: string }
   - State: const [messages, setMessages] = useState([]); const [input, setInput] = useState(''); const [loading, setLoading] = useState(false); const [error, setError] = useState(null);
   - Ref: const bottomRef = useRef(null); — useEffect scrolls bottomRef into view when messages change.
   - sendMessage async function:
       if (!input.trim() || loading) return;
       const userMsg = { id: Date.now(), role: 'user', content: input.trim() };
       setMessages(m => [...m, userMsg]);
       setInput('');
       setLoading(true);
       setError(null);
       try {
         const history = [...messages, userMsg].map(m => ({ role: m.role, content: m.content }));
         const fullMessages = [{ role: 'system', content: SYSTEM_PROMPT }, ...history];
         const res = await fetch('/api/generate', {
           method: 'POST',
           headers: { 'Content-Type': 'application/json' },
           body: JSON.stringify({ messages: fullMessages }),
         });
         if (!res.ok) {
           const e = await res.json().catch(() => ({}));
           throw new Error(e.error || `Request failed (${res.status})`);
         }
         const data = await res.json();
         const reply = data.choices?.[0]?.message?.content ?? '';
         setMessages(m => [...m, { id: Date.now() + 1, role: 'assistant', content: reply }]);
       } catch (err) {
         setError(err.message);
       } finally {
         setLoading(false);
       }
   - Layout:
     <div className="flex flex-col min-h-dvh pb-24">
       {/* Header */}
       <div className="px-4 pt-6 pb-3 border-b border-line bg-card sticky top-0 z-10">
         <div className="flex items-center gap-2">
           <Bot size={22} className="text-accent" />
           <h1 className="text-xl font-bold text-ink">AI Assistant</h1>
         </div>
         <p className="text-sm text-ink-soft">Ghanaian JHS Curriculum Assistant</p>
       </div>
       {/* Message thread */}
       <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4">
         {messages.length === 0 && (
           <div className="text-center py-12 text-ink-soft">
             <Bot size={40} className="mx-auto mb-3 text-accent/40" />
             <p className="text-sm">Ask me anything about the NaCCA curriculum,<br />lesson planning, or teaching strategies.</p>
           </div>
         )}
         {messages.map(msg => (
           <div key={msg.id} className={`flex gap-3 ${ msg.role === 'user' ? 'flex-row-reverse' : 'flex-row' }`}>
             <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${ msg.role === 'user' ? 'bg-accent text-white' : 'bg-card border border-line text-accent' }`}>
               {msg.role === 'user' ? <User size={14} /> : <Bot size={14} />}
             </div>
             <div className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${ msg.role === 'user' ? 'bg-accent text-white rounded-tr-sm' : 'bg-card border border-line text-ink rounded-tl-sm' }`}>
               <pre className="whitespace-pre-wrap font-sans">{msg.content}</pre>
             </div>
           </div>
         ))}
         {loading && (
           <div className="flex gap-3">
             <div className="shrink-0 w-8 h-8 rounded-full bg-card border border-line text-accent flex items-center justify-center">
               <Bot size={14} />
             </div>
             <div className="bg-card border border-line rounded-2xl rounded-tl-sm px-4 py-3">
               <Loader2 size={16} className="animate-spin text-accent" />
             </div>
           </div>
         )}
         {error && <p className="text-xs text-red-500 text-center">{error}</p>}
         <div ref={bottomRef} />
       </div>
       {/* Input bar */}
       <div className="sticky bottom-16 md:bottom-0 bg-card border-t border-line px-4 py-3">
         <form onSubmit={e => { e.preventDefault(); sendMessage(); }} className="flex gap-2">
           <input
             type="text"
             value={input}
             onChange={e => setInput(e.target.value)}
             placeholder="Ask about curriculum, lessons, activities…"
             className="flex-1 rounded-xl border border-line bg-paper px-4 py-2.5 text-sm text-ink placeholder:text-ink-soft focus:outline-none focus:border-accent"
             disabled={loading}
           />
           <button
             type="submit"
             disabled={!input.trim() || loading}
             className="shrink-0 w-10 h-10 rounded-xl bg-accent text-white flex items-center justify-center disabled:opacity-40 disabled:cursor-not-allowed hover:bg-accent/90"
           >
             {loading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
           </button>
         </form>
       </div>
     </div>
